n16224.content:
\begin{definition}[Weak convergence of probability measures]\label{def:weak_cvg_measure}
\mathlibok
\lean{MeasureTheory.ProbabilityMeasure.tendsto_iff_forall_integral_tendsto}
In a topological space $S$ in which the opens are measurable, we say that a sequence of probability measures $\mu_n$ converges weakly to a probability measure $\mu$ and write $\mu_n \xrightarrow{w} \mu$ if $\mu_n[f] \to \mu[f]$ for every bounded continuous function $f : S \to \mathbb{R}$.
\end{definition}

n16225.content:
\begin{definition}[Convergence in distribution]\label{def:cvg_distribution}
\uses{def:weak_cvg_measure}
\mathlibok
\lean{MeasureTheory.ProbabilityMeasure.tendsto_iff_forall_integral_tendsto}
We say that $X_n$ converges in distribution to $X$ and write $X_n \xrightarrow{d} X$ if $\mathcal L(X_n) \xrightarrow{w} \mathcal L(X)$.
\end{definition}

n16226.content:
\begin{definition}\label{def:tight}
\lean{MeasureTheory.IsTightMeasureSet} \mathlibok
A set $S$ of measures on $\Omega$ is tight if for all $\varepsilon > 0$ there exists a compact set $K$ such that for all $\mu \in S$, $\mu(K^c) \le \varepsilon$.
\end{definition}

n16227.content:
\begin{lemma}\label{lem:isTightMeasureSet_iff_norm}
\uses{def:tight}
\mathlibok
\lean{MeasureTheory.isTightMeasureSet_iff_tendsto_measure_norm_gt}
Let $S$ be a set of measures on a finite-dimensional normed space $E$. 
Then $S$ is tight iff $\lim_{r \to +\infty}\sup_{\mu \in S} \mu\{\Vert x \Vert > r\} = 0$.
\end{lemma}

n16229.content:
\begin{lemma}\label{lem:isTightMeasureSet_iff_sup_inner}
\uses{def:tight}
\mathlibok
\lean{MeasureTheory.isTightMeasureSet_iff_inner_tendsto}
Let $S$ be a set of measures on a finite-dimensional inner product space $E$.
Then $S$ is tight iff for all $y \in E$, $\lim_{r \to +\infty}\sup_{\mu \in S} \mu\{\vert\langle y, x\rangle\vert > r\} = 0$.
\end{lemma}

n16231.content:
\begin{lemma}\label{lem:isTightMeasureSet_iff_basis}
\uses{def:tight}
\leanok
\lean{isTightMeasureSet_iff_tendsto_limsup_inner}
Let $(\mu_n)_{n \in \mathbb{N}}$ be a sequence of measures on a finite-dimensional inner product space $E$. 
Then the set $\{\mu_n \mid n \in \mathbb{N}\}$ is tight iff for all $y \in E$, $\lim_{r \to +\infty}\limsup_{n \to \infty} \mu_n\{\vert\langle y, x\rangle\vert > r\} = 0$.
\end{lemma}

